<script setup lang="ts">
import { onMounted, ref } from 'vue';
import type { PartListResult } from '../types';
import Icon from './Icon.vue';
defineProps<{result:PartListResult;encoding:string;busy:boolean;progress:string}>();
const emit=defineEmits<{close:[];add:[]}>();const panel=ref<HTMLElement>();onMounted(()=>panel.value?.focus());
</script>
<template><div class="modal-overlay" @click.self="!busy && emit('close')"><section ref="panel" class="modal part-list-dialog" role="dialog" aria-modal="true" aria-label="清单导入预览" tabindex="-1"><header><h2>清单导入预览</h2><button class="icon-button" :disabled="busy" aria-label="关闭清单预览" @click="emit('close')"><Icon name="close"/></button></header><div class="part-list-body"><strong>{{result.fileName}}</strong><p class="field-hint">{{encoding.toUpperCase()}} · {{result.totalRows}} 行 · {{result.ids.length}} 个 C 编号 · 去重 {{result.duplicates}} 项</p><div v-if="result.warnings.length" class="part-warnings"><h4><Icon name="warning" :size="15"/>解析提示</h4><p v-for="(warning,index) in result.warnings" :key="index">{{warning}}</p></div><div class="part-list-ids"><span v-for="id in result.ids" :key="id" class="mono">{{id}}</span><p v-if="!result.ids.length">没有可添加的有效 C 编号。</p></div><p class="field-hint">仅获取清单中的完整 C 编号，不按型号猜测。确认后每批最多 50 个，依次获取实际符号与封装；最多 500 个。</p><p v-if="progress" class="part-list-progress" role="status">{{progress}}</p></div><footer><span>{{busy?'正在依次获取，请等待本次清单完成。':'确认后才会联网获取器件。'}}</span><div class="search-result-actions"><button class="secondary-button" :disabled="busy" @click="emit('close')">取消</button><button class="primary-button" :disabled="busy || !result.ids.length" @click="emit('add')"><span v-if="busy" class="spinner"></span><Icon v-else name="plus" :size="15"/>{{busy?'正在添加':'添加 '+result.ids.length+' 个器件'}}</button></div></footer></section></div></template>
